	if err != nil {
		fmt.Fprintln(os.Stderr, "lcprac: no history location:", err)
		return progress.New("")
	}
	store, err := progress.Load(path)
	if err != nil {
		fmt.Fprintln(os.Stderr, "lcprac: ignoring unreadable history:", err)
		return progress.New("")
	}
